sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float inBlack;
uniform float inWhite;
uniform float gamma;
uniform float outBlack;
uniform float outWhite;

half4 main(float2 coord) {
    half4 color = image.eval(coord);
    float alpha = color.a;
    if (alpha < 1e-6) {
        return half4(0);
    } else {
        half3 rgb = color.rgb / half3(alpha);
        float denom = inWhite - inBlack;
        denom = max(denom, 1e-5);
        half3 normalized = (rgb - half3(inBlack)) / half3(denom);
        normalized = clamp(normalized, half3(0.0), half3(1.0));
        half3 gammaed = pow(normalized, half3(gamma));
        gammaed = gammaed * half3(outWhite - outBlack) + half3(outBlack);
        gammaed = clamp(gammaed, half3(0.0), half3(1.0));
        return half4(gammaed * half3(alpha), alpha);
    }
}
